import{_ as r,o,c as t,a2 as s}from"./chunks/framework.BeNN5tyQ.js";const h=JSON.parse('{"title":"WebSocket, SSE, Web Worker, Service Worker","description":"","frontmatter":{},"headers":[],"relativePath":"browser/websocket-sse-workers.md","filePath":"browser/websocket-sse-workers.md"}'),i={name:"browser/websocket-sse-workers.md"};function l(a,e,n,c,k,d){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="websocket-sse-web-worker-service-worker" tabindex="-1">WebSocket, SSE, Web Worker, Service Worker <a class="header-anchor" href="#websocket-sse-web-worker-service-worker" aria-label="Permalink to &quot;WebSocket, SSE, Web Worker, Service Worker&quot;">​</a></h1><div><h2 id="_1-websocket" tabindex="-1">1. WebSocket <a class="header-anchor" href="#_1-websocket" aria-label="Permalink to &quot;1\\. WebSocket&quot;">​</a></h2><ul><li>Це <strong>постійне двостороннє з’єднання</strong>.</li><li>І клієнт, і сервер можуть відправляти повідомлення в будь-який момент.</li><li>Працює поверх TCP.</li><li>Найпотужніший варіант для real-time.</li></ul><p><strong>Приклад використання:</strong> чат, спільне редагування, онлайн-ігри, біржові котирування.</p><hr><h2 id="_2-server-sent-events-sse" tabindex="-1">2. Server-Sent Events (SSE) <a class="header-anchor" href="#_2-server-sent-events-sse" aria-label="Permalink to &quot;2\\. Server-Sent Events (SSE)&quot;">​</a></h2><ul><li>Це <strong>односторонній</strong> канал: тільки сервер надсилає дані клієнту.</li><li>Працює звичайним HTTP (простіше, ніж WebSocket).</li><li>Браузер сам перепідключається, якщо з’єднання порвалось.</li><li>Легший і часто достатній, коли не потрібно відправляти дані на сервер постійно.</li></ul><p><strong>Приклад:</strong> сповіщення, оновлення стрічки новин, прогрес довгої операції.</p><hr><h2 id="_3-web-worker" tabindex="-1">3. Web Worker <a class="header-anchor" href="#_3-web-worker" aria-label="Permalink to &quot;3\\. Web Worker&quot;">​</a></h2><ul><li>Це спосіб запустити <strong>JavaScript в окремому потоці</strong>.</li><li>Щоб важкі обчислення не блокували інтерфейс (не фризили сторінку).</li><li>Не має доступу до <code>window</code>, <code>document</code>, DOM.</li><li>Спілкування зі сторінкою тільки через <code>postMessage</code>.</li></ul><p><strong>Приклад:</strong> обробка великих масивів, парсинг великих JSON, складні розрахунки, шифрування.</p><hr><h2 id="_4-service-worker" tabindex="-1">4. Service Worker <a class="header-anchor" href="#_4-service-worker" aria-label="Permalink to &quot;4\\. Service Worker&quot;">​</a></h2><ul><li>Це <strong>фоновий скрипт</strong>, який сидить між сторінкою і мережею.</li><li>Може перехоплювати всі запити (<code>fetch</code>), кешувати їх, відповідати з кешу.</li><li>Працює навіть коли вкладка закрита (для push і background sync).</li><li>Не для обчислень, а для <strong>керування мережею та офлайн-режимом</strong>.</li></ul><p><strong>Приклад:</strong> PWA, офлайн-режим, кешування статичних файлів, push-повідомлення.</p><hr><h2 id="чому-іх-плутають" tabindex="-1">Чому їх плутають? <a class="header-anchor" href="#чому-іх-плутають" aria-label="Permalink to &quot;Чому їх плутають?&quot;">​</a></h2><p>Бо всі чотири:</p><ul><li>Працюють асинхронно</li><li>Не блокують основний потік</li><li>Не мають прямого доступу до DOM</li><li>Звучать як «щось фонове»</li></ul><p>Але насправді вони вирішують <strong>зовсім різні задачі</strong>:</p><ul><li>Потрібен постійний зв’язок з сервером у обидва боки → <strong>WebSocket</strong></li><li>Потрібно тільки отримувати події з сервера → <strong>SSE</strong></li><li>Потрібно порахувати щось важке і не зафризити сторінку → <strong>Web Worker</strong></li><li>Потрібен офлайн, кеш і push → <strong>Service Worker</strong></li></ul></div>',2)])])}const S=r(i,[["render",l]]);export{h as __pageData,S as default};
